function M.get()
    if cached ~= nil then return cached end
    local n = #PAIR_VALUES
    local buf = ffi.new('JournalImWchar[?]', n + 1) -- Required zero terminator; buffer remains module-owned.
    for i = 1, n do buf[i - 1] = PAIR_VALUES[i] end
    cached = buf
    return cached
end

